import{_ as e,o,c as n,ah as s}from"./chunks/framework.BK78naE0.js";const i="/projects/JetMaxPro/en/latest/assets/image2.BWPTgHm5.webp",a="/projects/JetMaxPro/en/latest/assets/image3.BUA6UjaN.webp",c="/projects/JetMaxPro/en/latest/assets/image4.DVvYjABn.webp",l="/projects/JetMaxPro/en/latest/assets/image5.Bb8xpL_M.webp",r="/projects/JetMaxPro/en/latest/assets/image6.DpItdnI_.webp",m="/projects/JetMaxPro/en/latest/assets/image7.BbUraXLg.webp",g="/projects/JetMaxPro/en/latest/assets/image8.2LmN0LAN.webp",p="/projects/JetMaxPro/en/latest/assets/image9.o_3erQ4m.webp",h="/projects/JetMaxPro/en/latest/assets/image10.D14SZ-wO.webp",d="/projects/JetMaxPro/en/latest/assets/image11.DS3blUKh.webp",_="/projects/JetMaxPro/en/latest/assets/image12.BgdvDQ-q.webp",w="/projects/JetMaxPro/en/latest/assets/image13.wjxJIodg.webp",y="/projects/JetMaxPro/en/latest/assets/image14.r3cCLtpM.webp",u="/projects/JetMaxPro/en/latest/assets/image15.Cl03Z-DZ.webp",x="/projects/JetMaxPro/en/latest/assets/image16.CVYH_iEi.webp",P="/projects/JetMaxPro/en/latest/assets/image17.BVAYsvxQ.webp",M="/projects/JetMaxPro/en/latest/assets/image18.CshKX0c-.webp",S="/projects/JetMaxPro/en/latest/assets/image19.ClSqgLiV.webp",b="/projects/JetMaxPro/en/latest/assets/image20.CsnkM240.webp",J="/projects/JetMaxPro/en/latest/assets/image21.g20co2xR.webp",C="/projects/JetMaxPro/en/latest/assets/image22.CBCRQwhU.webp",f="/projects/JetMaxPro/en/latest/assets/image23.Bn14D2c4.webp",j="/projects/JetMaxPro/en/latest/assets/image24.CPMLNLOm.webp",k="/projects/JetMaxPro/en/latest/assets/image25.BKZLdqzg.webp",I="/projects/JetMaxPro/en/latest/assets/image26.BSIKZTBH.webp",z="/projects/JetMaxPro/en/latest/assets/image27.DfwthAfS.webp",q=JSON.parse('{"title":"7. Robot System Remote Connection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/7.Robot System Remote Connection.md","filePath":"docs/7.Robot System Remote Connection.md"}'),N={name:"docs/7.Robot System Remote Connection.md"};function R(T,t,v,B,A,L){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_7-robot-system-remote-connection" tabindex="-1">7. Robot System Remote Connection <a class="header-anchor" href="#_7-robot-system-remote-connection" aria-label="Permalink to &quot;7. Robot System Remote Connection&quot;">​</a></h1><h2 id="_7-1-remote-tool-installation-and-connection" tabindex="-1">7.1 Remote Tool Installation and Connection <a class="header-anchor" href="#_7-1-remote-tool-installation-and-connection" aria-label="Permalink to &quot;7.1 Remote Tool Installation and Connection&quot;">​</a></h2><p><strong>Remote Tool Installation and Connection</strong></p><h3 id="_7-1-1-nomachine" tabindex="-1">7.1.1 NoMachine <a class="header-anchor" href="#_7-1-1-nomachine" aria-label="Permalink to &quot;7.1.1 NoMachine&quot;">​</a></h3><h3 id="_7-1-2-install-nomachine" tabindex="-1">7.1.2 Install NoMachine <a class="header-anchor" href="#_7-1-2-install-nomachine" aria-label="Permalink to &quot;7.1.2 Install NoMachine&quot;">​</a></h3><ol><li><p>Install NoMachine. The installation pack “<strong>nomachine_7.1.3_1.exe</strong>” is stored in the same folder.</p></li><li><p>Click ‘Next’.</p><img loading="lazy" height="385" width="497" class="common_img" src="'+i+'" style="width:800px;"></li><li><p>Select language to use, and tick “I accept the agreement”.</p><img loading="lazy" height="385" width="497" class="common_img" src="'+a+'" style="width:800px;"></li><li><p>Remain the default destination location</p><img loading="lazy" height="385" width="497" class="common_img" src="'+c+'" style="width:800px;"></li><li><p>It takes a few times to complete installation. Please be patient! Later on, click “<strong>Finish</strong>” when window below shows up.</p><img loading="lazy" height="385" width="497" class="common_img" src="'+l+'" style="width:800px;"></li><li><p>Click “Yes” to restart computer. Please don’t skip this step!</p></li></ol><img loading="lazy" height="213" width="459" class="common_img" src="'+r+'" style="width:800px;"><h3 id="_7-1-3-device-connection" tabindex="-1">7.1.3 Device connection <a class="header-anchor" href="#_7-1-3-device-connection" aria-label="Permalink to &quot;7.1.3 Device connection&quot;">​</a></h3><p>You can connect to robot in three ways.</p><p>①AP direct connection: connect your phone to WiFi generated by Jetson Nano board. Jetson Nano cannot connect to external network in this mode.</p><p>②STA LAN mode: Jetson Nano automatically connects to specific hotspot/ WiFi.</p><p>③USB connection: connect Jetson Nano to computer through USB cable. Then input fixed IP to connect.</p><p><strong>1.2.1 AP Direct Connection/ STA LAN Mode</strong></p><ol><li>The default connection mode is AP direct connection mode. Once JetMax boots up successfully, it will create a Wi-Fi starting with HW. Connect your computer to this WiFi.</li></ol><img loading="lazy" height="176" width="354" class="common_img" src="'+m+'" style="width:600px;"><ol start="2"><li>Open NoMachine. Input ‘<strong>192.168.149.1</strong>’ in the search bar, then click ‘<strong>Configure connection to new host 192.168.149.1</strong>’.</li></ol><img loading="lazy" height="154" width="843" class="common_img" src="'+g+'" style="width:800px;"><ol start="3"><li><p>You can change the name as ‘JetMax’, and other settings remain the same. Click ‘<strong>Connect</strong>’</p><img loading="lazy" height="557" width="847" class="common_img" src="'+p+'" style="width:800px;"></li><li><p>Username is ‘hiwonder’, and password is ‘<strong>hiwonder</strong>’. Tick ‘Save this password’ and click ‘Login’ to get access to Jetson Nano desktop.</p><img loading="lazy" height="607" width="897" class="common_img" src="'+h+'" style="width:800px;"><p>Note: connection instructions under STA LAN mode are the same. You just need to change the corresponding IP, username and password in step 2, 3 and 4.</p><img loading="lazy" height="575" width="895" class="common_img" src="'+d+'" style="width:800px;"><img loading="lazy" height="575" width="895" class="common_img" src="'+_+'" style="width:800px;"><img loading="lazy" height="575" width="895" class="common_img" src="'+w+'" style="width:800px;"><img loading="lazy" height="691" width="1304" class="common_img" src="'+y+'" style="width:800px;"></li></ol><h3 id="_7-1-4-usb-connection" tabindex="-1">7.1.4 USB Connection <a class="header-anchor" href="#_7-1-4-usb-connection" aria-label="Permalink to &quot;7.1.4 USB Connection&quot;">​</a></h3><p>If you are using desktop computer, you can use remote NDIS compatible device to improve running.</p><ol><li><p>Connect JetMax to your computer through Micro USB cable.</p><img loading="lazy" height="574" width="1020" class="common_img" src="'+u+'" style="width:800px;"></li><li><p>Right click ‘<strong>This computer</strong>’ to select ‘<strong>Manage</strong>’</p><img loading="lazy" height="270" width="326" class="common_img" src="'+x+'" style="width:800px;" alt="IMG_256"></li><li><p>Click ‘<strong>device manager&gt; network adapter&gt;remote NDIS compatible device</strong>’. Then right click it to update driver.</p><img loading="lazy" height="708" width="986" class="common_img" src="'+P+'" style="width:800px;"></li><li><p>After installing the driver, login the system according to ‘<strong>2. Device Connection</strong>’. IP is ‘192.168.55.1’</p></li></ol><ol start="2"><li><p><strong>SSH Remote Connection</strong></p><p>You can get access to robot system through SSH. Compared to SSH, SSH cannot get access to robot system desktop and provide only command terminal making it convenient to control JetMax with command. Therefore you don’t need open too much windows, which saves computation and storage.</p><ol><li><strong>Install SSH</strong></li></ol></li></ol><ol><li><p>Find ‘<strong>putty-64bit-0.72-installer.msi</strong>’ file stored in ‘<strong>7. Robot System Remote Connection&gt;Software</strong>’, and install it.</p><img loading="lazy" height="387" width="495" class="common_img" src="'+M+'" style="width:800px;"></li><li><p>Select folder, and click ‘<strong>Next</strong>’</p><img loading="lazy" height="387" width="495" class="common_img" src="'+S+'" style="width:800px;"></li><li><p>Install SSH</p><img loading="lazy" height="387" width="495" class="common_img" src="'+b+'" style="width:800px;"><p>Installation is completed when window below pops up.</p><img loading="lazy" height="387" width="495" class="common_img" src="'+J+'" style="width:800px;"><ol><li><strong>Use SSH</strong></li></ol></li><li><p>After installation, open Putty software. Input IP ‘<strong>192.168.149.1</strong>’, and ensure the computer and JetMax connect to the same WiFi. Security alert window will show up, just click ‘<strong>yes</strong>’.</p><p><img loading="lazy" height="442" width="452" class="common_img" src="'+C+'" style="width:800px;"><img loading="lazy" height="396" width="433" src="'+f+'" style="width:800px;"></p><img loading="lazy" height="316" width="431" class="common_img" src="'+j+'" style="width:800px;"></li><li><p>Input username and password. Username and password are both hiwonder. Pay attention the content you input will be hidden, and you can press Enter once you finish.</p><img loading="lazy" height="418" width="661" class="common_img" src="'+k+'" style="width:800px;"><p>If the password is wrong, terminal will print ‘<strong>access denied</strong>’.</p><img loading="lazy" height="418" width="661" class="common_img" src="'+I+'" style="width:800px;"></li><li><p>Having successfully login JetMax system, you can control JetMax through command. To learn more about command, you can refer to ‘<strong>2. Linux Basic Lesson&gt;Lesson 6 Common Linux Command</strong>’.<img loading="lazy" height="418" width="662" class="inline-icon" src="'+z+'" alt="IMG_256"></p></li></ol>',23)])])}const U=e(N,[["render",R]]);export{q as __pageData,U as default};
